"""Authored commercial-intent pages; vendor facts are deliberately narrowly scoped."""
import json
from html import escape as e
from pathlib import Path
from expansion_content import p, ul, table, guide

RESEARCH = json.loads((Path(__file__).parent / 'data/commercial-sources.json').read_text())


def cite(key, text=None):
    source = RESEARCH['sources'][key]
    return '<a href="' + source['url'] + '">' + e(text or source['title']) + '</a>'


def resource(slug, title, description, intro, sections, links, kind, parent, sources=()):
    item = guide(slug, title, description, intro, sections, links, kind, parent)
    item['sources'] = list(sources)
    if sources:
        item['sections'].append(('Sources and editorial method',
            p('Vendor information checked on ' + RESEARCH['checked_on'] + '. Product facts come from the official pages linked below. Fit recommendations and trial scenarios are Elixir’s editorial analysis, not a claim of hands-on product testing or vendor certification. Elixir publishes this guide and offers implementation consulting.')
            + '<ul>' + ''.join('<li>' + cite(key) + '</li>' for key in sources) + '</ul>'))
    return item


