def operational_comparisons():
    pages = []
    for c in COMPARISONS:
        sections = [('Comparison at a glance', table(c['title'], ['Decision', c['a'], c['b']], c['rows'])),
                    ('When the first approach fits', p(c['choose_a'])), ('When the second approach fits', p(c['choose_b'])),
                    ('Worked decision example', p(c['example'])), ('A practical selection test', p(c['test'])),
                    ('What the proposal must resolve', p('Ask for the exact work boundary, internal counterpart, access requirements, deliverables, and acceptance evidence. Clarify what happens when new information changes the brief. Compare the work your team must still perform, not only the outside fee or the name of the service.'))]
        if c['slug'] == 'ai-vs-rule-based-automation':
            sections.insert(1, ('How the distinction appears in product documentation', '<p>Microsoft documents event- and time-triggered flows in ' + cite('cloud_flows') + ' and describes adding a prompt action and human review in ' + cite('ai_review') + '. These are implementation patterns, not proof that a particular workflow is ready for autonomous operation.</p>'))
        pages.append(resource(c['slug'], c['title'], 'Compare ' + c['a'].lower() + ' and ' + c['b'].lower() + ' by responsibilities, outputs, fit, and acceptance before committing to implementation.', c['intro'], sections, c['links'], 'Comparison', '/compare/', c['sources']))
    return pages


