def operational_alternatives():
    pages = []
    for a in ALTERNATIVES:
        sections = [('Options and the work each one addresses', table(a['title'], ['Alternative', 'When to consider it', 'Responsibility to resolve'], a['rows'])),
                    ('Diagnose the gap before choosing', p(a['diagnosis'])), ('Worked decision example', p(a['example'])),
                    ('Compare the full commitment', p(a['check'])),
                    ('Make the next step testable', p('Choose one unresolved operating question and gather the evidence needed to answer it. Name the person who will maintain the result, define what a useful pilot must show, and agree on a review date. If the alternative cannot explain its work boundary or your remaining responsibilities, clarify those items before committing.'))]
        if a['sources']:
            sections.insert(1, ('The framework being compared', '<p>See the official ' + cite('eos', 'EOS Model description') + ' for the framework’s own explanation. The alternatives here are different support approaches and are not presented as certified or identical substitutes.</p>'))
        pages.append(resource(a['slug'], a['title'], 'Explore ' + a['title'].lower() + ' with practical fit criteria, internal responsibilities, and a decision checklist before spending.', a['intro'], sections, a['links'], 'Alternatives', '/alternatives/', a['sources']))
    return pages


