def software_pricing():
    pages = []
    for item in SOFTWARE_PRICING:
        sources = [item['source']]
        if item['slug'] == 'pipedrive':
            sources.append('pipedrive_billing')
        sections = [('Published pricing snapshot', table(item['title'], item['heads'], item['rows'])
                    + '<p>Source: ' + cite(item['source']) + '. Checked ' + RESEARCH['checked_on'] + '.</p>'),
                    ('Read the billing basis correctly', p(item['note'])), ('Build the complete implementation budget', p(item['budget'])),
                    ('Worked budgeting example', p(item['example'])), ('Questions for the written quote', ul(item['questions'])),
                    ('Software fees and Elixir fees are separate', p('The figures or quote requirements above concern the named software vendor. Elixir’s consulting work is scoped separately around the business process, data, configuration, training, and handover required. No vendor rate on this page is presented as an Elixir package price.'))]
        if item['slug'] == 'pipedrive':
            sections[1] = (sections[1][0], sections[1][1] + '<p>See ' + cite('pipedrive_billing') + ' for the vendor’s explanation of seats, billing cycles, add-ons, and top-ups.</p>')
        pages.append(resource(item['slug'], item['title'], 'Review ' + item['title'].lower() + ', official pricing sources, billing conditions, implementation scope, and questions for a written quote.', item['intro'], sections, item['links'], 'Pricing guide', '/pricing/', sources))
    return pages


